const receiptVisualStyle=document.createElement('style');receiptVisualStyle.textContent="\n/* Recibo aprovado: visualizacao compacta alinhada ao modelo Areia Amigos */\n#areiaamigos-view .av-paper{width:100%;max-width:520px;margin:10px auto 16px;border:4px solid #fff;border-radius:15px;overflow:hidden;background:#fff;box-shadow:0 5px 22px #071b3030;color:#152235;font-family:Arial,sans-serif}\n#areiaamigos-view .av-paper-brand{height:72px;display:flex;align-items:center;gap:10px;padding:8px 12px;background:linear-gradient(120deg,#071b32 0%,#00294b 77%,#ff9100 77%);color:white}\n#areiaamigos-view .av-truck{font-size:40px;line-height:1}\n#areiaamigos-view .av-paper-name{flex:1;min-width:0}\n#areiaamigos-view .av-paper-name strong{font-size:clamp(17px,3.5vw,25px);white-space:nowrap}\n#areiaamigos-view .av-paper-name em{font-style:normal;color:#ff9900}\n#areiaamigos-view .av-paper-name small{display:block;font-size:8px;letter-spacing:2px;margin-top:4px}\n#areiaamigos-view .av-fixcol{font-size:19px;color:#d91c39;font-style:italic;white-space:nowrap}\n#areiaamigos-view .av-paper-body{padding:8px 12px 12px}\n#areiaamigos-view .av-paper-body h3,#areiaamigos-view .av-paper-body h4{margin:0;background:linear-gradient(#003353,#051a30);color:#fff;border-radius:4px}\n#areiaamigos-view .av-paper-body h3{text-align:center;font-size:13px;padding:10px 3px;margin-bottom:8px}\n#areiaamigos-view .av-paper-body h4{font-size:11px;padding:5px 12px;margin-top:10px}\n#areiaamigos-view .av-paper-meta{display:grid;grid-template-columns:1fr 1.45fr 1fr;gap:7px}\n#areiaamigos-view .av-paper-meta>div{background:linear-gradient(#f6f7f9,#e8edf1);border-radius:5px;min-height:43px;text-align:center;padding:6px 2px;display:flex;flex-direction:column;gap:3px}\n#areiaamigos-view .av-paper-meta>div:first-child{background:#ff9000;color:white}\n#areiaamigos-view .av-paper-meta small{font-size:8px}\n#areiaamigos-view .av-paper-meta strong{font-size:13px}\n#areiaamigos-view .av-card-line{display:grid;grid-template-columns:42% 58%;padding:5px 12px;font-size:11px;min-height:23px}\n#areiaamigos-view .av-card-line:nth-of-type(even){background:#e9edf2}\n#areiaamigos-view .av-card-line strong{overflow-wrap:anywhere}\n#areiaamigos-view .av-paper-total{margin-top:8px;display:flex;justify-content:space-between;align-items:center;padding:10px 12px;background:linear-gradient(115deg,#052b48 0%,#052b48 52%,#f79400 52%);color:white;font-weight:bold;font-size:12px}\n#areiaamigos-view .av-paper-total strong{font-size:15px}\n";document.head.append(receiptVisualStyle);
